// Flow B – Aufträge sammeln (v0.1)
// Eingang A: Aufruf aus Flow A -> Items mit { update_path }
// Eingang B: "Manuell nachholen" -> alle Update-Dateien (Binärdaten); nur Updates ab Flow-A-Version v0.8
const ROOT = '/vault/Finanzen/Trading/Research/Analysten/The Long Investor';
const RE = /^\/vault\/Finanzen\/Trading\/Research\/Analysten\/The Long Investor\/(Technisch|Fundamental)\/[^/]+\/Updates\/\d{4}-\d{2}-\d{2} - [^/]+\.md$/;
const out = [], seen = new Set();
const ins = $input.all();
for (let i = 0; i < ins.length; i++) {
  const it = ins[i];
  let p = it.json && it.json.update_path;
  if (!p && it.binary && it.binary.data) {
    const b = it.binary.data;
    p = `${b.directory}/${b.fileName}`;
    const txt = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
    const m = txt.match(/workflow:\s*"?FinVault Patreon → Vault v(\d+)\.(\d+)/);
    if (!m || (Number(m[1]) === 0 && Number(m[2]) < 8)) continue; // alte Formate: kein Status-Aufbau
  }
  if (!p || !p.startsWith(ROOT + '/') || p.includes('..') || !RE.test(p) || seen.has(p)) continue;
  seen.add(p);
  out.push({ update_path: p, datum: p.split('/').pop().slice(0, 10) });
}
out.sort((a, b) => (a.datum + a.update_path).localeCompare(b.datum + b.update_path));
return out.map(j => ({ json: j }));

// Flow B – Vorbereitung (v0.1): Status-Template einlesen und an jeden Auftrag hängen
const bin = $input.first().binary && $input.first().binary.data;
if (!bin) throw new Error('Template Trading/Templates/Analysten-Wertpapierstatus.md nicht gefunden');
const template = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
return $('Aufträge sammeln').all().map(i => ({ json: { ...i.json, template } }));

// Flow B – Update auswerten (v0.1): Update-Datei zerlegen (Frontmatter, Abschnitte, Marken)
const it = $input.first();
const b = it.binary && it.binary.data;
if (!b) throw new Error('Update-Datei nicht gefunden');
const text = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/\r/g, '');
const path = `${b.directory}/${b.fileName}`;
const name = b.fileName.replace(/\.md$/, '');
const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// Frontmatter (einfaches YAML: key: wert / Listen mit "  - ")
const fm = {};
const m = text.match(/^---\s*\n([\s\S]*?)\n---\s*\n?([\s\S]*)$/);
const body = m ? m[2] : text;
if (m) {
  let cur = null;
  for (const l of m[1].split('\n')) {
    const kv = l.match(/^([^\s:#-][^:]*):\s*(.*)$/);
    if (kv) { cur = norm(kv[1]).replace(/ /g, '_'); const v = kv[2].trim(); fm[cur] = v === '' ? [] : v.replace(/^"(.*)"$/, '$1'); continue; }
    const li = l.match(/^\s+-\s+(.*)$/);
    if (li && cur && Array.isArray(fm[cur])) fm[cur].push(li[1].trim().replace(/^"(.*)"$/, '$1'));
  }
}
// Abschnitte (## und ###)
const sec = {}; let cur = null;
for (const l of body.split('\n')) {
  const h = l.match(/^(#{2,3})\s+(.*)$/);
  if (h) { cur = norm(h[2]); sec[cur] = []; continue; }
  if (cur) sec[cur].push(l);
}
const get = (...keys) => { for (const k of Object.keys(sec)) if (keys.some(x => k.startsWith(x))) return sec[k].join('\n').trim(); return ''; };

// Marken aus den Listen ("- 143 USD – Text (Notiz)" bzw. "- 140 – 150 USD – Text")
const toNum = s => Number(String(s).replace(/\./g, '').replace(',', '.'));
const NUM = '(\\d{1,3}(?:\\.\\d{3})*(?:,\\d+)?|\\d+(?:,\\d+)?)';
const reLevel = new RegExp(`^${NUM}(?:\\s*–\\s*${NUM})?\\s+([A-Z]{3}|\\$|€)(?:\\s+–\\s+(.*))?$`);
const marken = [];
const ARTEN = [['unterstutzung', 'unterstuetzung'], ['widerstand', 'widerstand'], ['kauf', 'zone'], ['invalidation', 'invalidation'], ['kursziel', 'kursziel']];
for (const [prefix, art] of ARTEN) {
  for (const l of get(prefix).split('\n')) {
    const s = l.replace(/^\s*-\s+/, '').trim();
    if (!l.trim().startsWith('-') || !s || /^nicht genannt/i.test(s)) continue;
    const x = s.match(reLevel);
    const mk = x
      ? { art, wert: toNum(x[1]), wert_bis: x[2] ? toNum(x[2]) : null, waehrung: x[3] === '$' ? 'USD' : x[3] === '€' ? 'EUR' : x[3], beschreibung: (x[4] || '').trim() }
      : { art, wert: null, wert_bis: null, waehrung: '', beschreibung: s };
    mk.id = 'N' + (marken.length + 1);
    marken.push(mk);
  }
}
// Inhalt für den Abgleich: alles außer Verwaltungsabschnitten (Originaltext bleibt für Belege drin)
const SKIP = ['anderungen gegenuber', 'quellenangabe', 'verknupfungen'];
let kern = [], skip = false;
for (const l of body.split('\n')) {
  const h = l.match(/^(#{1,3})\s+(.*)$/);
  if (h) skip = SKIP.some(x => norm(h[2]).startsWith(x));
  if (skip || /^!\[\[/.test(l)) continue;
  kern.push(l);
}
const datum = String(fm.veroffentlicht || fm.veroeffentlicht || name.slice(0, 10)).slice(0, 10);
const ticker = String(fm.ticker || name.split(' - ')[1] || '').toUpperCase().replace(/[^A-Z0-9._-]/g, '');
if (!/^\d{4}-\d{2}-\d{2}$/.test(datum) || !ticker) throw new Error('Datum oder Ticker fehlt in ' + name);
const tickerDir = b.directory.replace(/\/Updates$/, '');
const kategorie = tickerDir.split('/').slice(-2, -1)[0];
return [{ json: {
  update_path: path, name, datum, ticker, kategorie, ticker_dir: tickerDir,
  instrument: typeof fm.instrument === 'string' ? fm.instrument : '',
  konzepte: Array.isArray(fm.konzepte) ? fm.konzepte : [],
  marken, kern: kern.join('\n').replace(/\n{3,}/g, '\n\n').trim(),
  state_path: `/vault/Finanzen/Trading/System/Automation/status-state/${ticker}.json`,
} }];

// Flow B – Status-Daten auswerten (v0.1): bisherigen Stand (JSON) laden, falls vorhanden
const it = $input.first();
if (!it.binary || !it.binary.data) return [{ json: { state: null } }];
const txt = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
let state;
try { state = JSON.parse(txt); } catch (e) { throw new Error('Status-Daten sind kein gültiges JSON: ' + e.message); }
return [{ json: { state } }];

// Flow B – Abgleich vorbereiten (v0.1)
// Eingang: concept-links.json (Register lesen); Update + bisheriger Stand aus den Nodes davor.
// Baut die Claude-Anfrage: NUR neues Update gegen bisherigen Stand (nicht alle Updates).
const MODEL = 'claude-haiku-5-5';
const PROMPT_VERSION = 'status-abgleich-v1';
const upd = $('Update auswerten').first().json;
const state = $('Status-Daten auswerten').first().json.state;
const template = $('Vorbereitung').first().json.template;
const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// Theorie-Links: Begriffe aus dem Update über das Register auflösen (inkl. Aliasse, Hauptthemen)
const links = [];
const bin = $input.first().binary && $input.first().binary.data;
if (bin) {
  const reg = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'));
  const lookup = {};
  for (const h of reg.hauptthemen || []) if (h.hauptthema && h.zielpfad) lookup[norm(h.hauptthema)] = { begriff: h.hauptthema, ziel: h.zielpfad };
  for (const k of reg.konzepte || []) {
    if (!k.begriff || !k.zielpfad) continue;
    for (const n of [k.begriff, ...(k.aliases || [])]) { const key = norm(n); if (key && (!lookup[key] || k.primaer)) lookup[key] = { begriff: k.begriff, ziel: k.zielpfad }; }
  }
  for (const b of upd.konzepte) { const e = lookup[norm(b)]; if (e && !links.some(l => l.ziel === e.ziel)) links.push({ begriff: b, ziel: e.ziel.replace(/\.md$/, '') }); }
}

const ctx = { upd: { ...upd }, state, template, links, prompt_version: PROMPT_VERSION, model: MODEL };
if (state && (state.updates || []).some(u => u.update === upd.name)) return [{ json: { aktion: 'ueberspringen', grund: 'bereits im Status', ...ctx } }];
const nachtrag = !!(state && state.stand && upd.datum < state.stand.datum);
ctx.nachtrag = nachtrag;

const ART = { unterstuetzung: 'Unterstützung', widerstand: 'Widerstand', zone: 'Kauf-/Beobachtungszone', kursziel: 'Kursziel', invalidation: 'Invalidation' };
const de = v => Number(v).toLocaleString('de-DE', { maximumFractionDigits: 2 });
const wert = m => m.wert == null ? '(ohne Kurs)' : (m.wert_bis != null ? `${de(m.wert)} – ${de(m.wert_bis)}` : de(m.wert)) + ` ${m.waehrung || 'USD'}`;
const SECS = {
  kurzueberblick: 'Kurzüberblick (2–3 Sätze Gesamtbild)',
  primaerszenario: 'Aktives Primärszenario',
  alternatives_szenario: 'Alternatives Szenario',
  trigger: 'Entscheidende Trigger (Liste: Kursmarken/Ereignisse, die das Szenario laut Analyst bestätigen oder kippen)',
  elliott: 'Elliott-Wellen-Stand',
  trend: 'Trendstruktur',
  gleitende_durchschnitte: 'Gleitende Durchschnitte (Liste: genannte Durchschnitte mit Kurs und Bedeutung)',
  fibonacci: 'Fibonacci-Niveaus (Liste: genannte Niveaus mit Kurs und Bedeutung)',
  ausstehende_bestaetigungen: 'Noch ausstehende Bestätigungen (Liste)',
  risiken: 'Unsicherheiten und Risiken (Liste)',
};

const aktive = state ? (state.marken || []).filter(m => m.status === 'aktiv') : [];
const alt = [
  `## BISHERIGER STAND${state ? ` (Stand ${state.stand.datum})` : ' – noch keiner vorhanden'}`,
  '### Aktive Marken',
  aktive.length ? aktive.map(m => `${m.id} | ${ART[m.art] || m.art} | ${wert(m)} | ${m.beschreibung || ''} | erstmals ${m.erstmals.datum} | zuletzt ${m.zuletzt.datum}`).join('\n') : '(keine)',
  '### Abschnitte',
  ...Object.entries(SECS).map(([k, t]) => `[${k}] ${t}:\n${(state && state.abschnitte && state.abschnitte[k] && state.abschnitte[k].text) || '(leer)'}`),
].join('\n');
const neu = [
  `## NEUES UPDATE vom ${upd.datum}${nachtrag ? ' – NACHTRAG (älter als der bisherige Stand, darf nur ergänzen)' : ''}`,
  '### Marken im Update',
  upd.marken.length ? upd.marken.map(m => `${m.id} | ${ART[m.art]} | ${wert(m)} | ${m.beschreibung}`).join('\n') : '(keine)',
  '### Inhalt des Updates',
  upd.kern,
].join('\n');

const SYSTEM = `Du pflegst den aktuellen Analystenstand (Status) zu einem Wertpapier. Grundlage sind ausschließlich (a) der bisherige Stand und (b) EIN neues Analysten-Update des Analysten "The Long Investor". Du gleichst nur dieses neue Update mit dem bisherigen Stand ab.

Regeln:
1. Verwende nur Informationen aus dem bisherigen Stand und dem neuen Update. Keine eigenen Einschätzungen, keine eigenen Kursmarken, keine Berechnungen, kein Allgemeinwissen.
2. Formuliere sachlich auf Deutsch als Einschätzung des Analysten (z. B. "Der Analyst erwartet ...").
3. bisherige_marken: Gib für JEDE bisherige Marke (M...) genau eine Aktion an:
   - bestaetigt: Das Update nennt dieselbe Marke (gleicher Kurs) erneut. neue_marke = passende N-ID.
   - geaendert: Das Update ersetzt diese Marke ausdrücklich durch eine andere (z. B. verschobene Invalidation, neues Kursziel anstelle des alten). neue_marke = N-ID, beleg = wörtliches Zitat aus dem Update.
   - aufgehoben: Das Update sagt ausdrücklich, dass die Marke nicht mehr gilt (gebrochen, erreicht, verworfen). beleg = wörtliches Zitat aus dem Update in Originalsprache.
   - nicht_erwaehnt: Das Update sagt nichts dazu. Im Zweifel immer nicht_erwaehnt. Nicht erwähnte Marken bleiben gültig.
   Marken aus dem Update (N...), die zu keiner bisherigen Marke gehören, werden automatisch als neu übernommen. Du musst sie nicht auflisten.
4. abschnitte: Für jeden Abschnitt genau eine Aktion:
   - unveraendert: Das Update enthält dazu nichts Neues und bestätigt es auch nicht ausdrücklich.
   - bestaetigt: Das Update sagt inhaltlich dasselbe wie der bisherige Stand.
   - aktualisiert: Das Update bringt neue oder geänderte Aussagen. text = vollständiger neuer Abschnittstext: weiterhin gültige bisherige Aussagen und neue Aussagen zusammengeführt, überholte Aussagen fallen weg.
   - leer: Weder bisheriger Stand noch Update enthalten dazu etwas.
   Gibt es noch keinen bisherigen Stand, ist jeder Abschnitt, zu dem das Update etwas sagt, "aktualisiert".
5. Form: kurzueberblick 2–3 Sätze; primaerszenario, alternatives_szenario, elliott, trend kurzer Fließtext; trigger, gleitende_durchschnitte, fibonacci, ausstehende_bestaetigungen, risiken als Liste mit einer Zeile je Punkt, beginnend mit "- ". Kursmarken mit Währung (z. B. 143 USD).
6. NACHTRAG (Update älter als der bisherige Stand): darf nur ergänzen. Keine Marke als geaendert oder aufgehoben markieren. Abschnitte nur "aktualisiert", wenn sie bisher leer sind.
7. Keine Links, kein HTML, keine Überschriften im Text.`;

const SEC = { type: 'object', properties: { aktion: { type: 'string', enum: ['unveraendert', 'bestaetigt', 'aktualisiert', 'leer'] }, text: { type: 'string' } }, required: ['aktion'] };
const tool = {
  name: 'status_abgleich',
  description: 'Ergebnis des Abgleichs zwischen bisherigem Stand und neuem Update speichern.',
  input_schema: {
    type: 'object',
    properties: {
      bisherige_marken: { type: 'array', items: { type: 'object', properties: {
        id: { type: 'string' },
        aktion: { type: 'string', enum: ['bestaetigt', 'geaendert', 'aufgehoben', 'nicht_erwaehnt'] },
        neue_marke: { type: 'string', description: 'N-ID aus dem Update (bei bestaetigt/geaendert)' },
        beleg: { type: 'string', description: 'Wörtliches Zitat aus dem Update (bei geaendert/aufgehoben)' },
      }, required: ['id', 'aktion'] } },
      abschnitte: { type: 'object', properties: Object.fromEntries(Object.keys(SECS).map(k => [k, SEC])), required: Object.keys(SECS) },
    },
    required: ['bisherige_marken', 'abschnitte'],
  },
};
const request = {
  model: MODEL, max_tokens: 3000, system: SYSTEM,
  tools: [tool], tool_choice: { type: 'tool', name: 'status_abgleich' },
  messages: [{ role: 'user', content: `WERTPAPIER: ${upd.ticker}\n\n${alt}\n\n${neu}` }],
};
return [{ json: { aktion: 'abgleich', request, ...ctx } }];

// Flow B – Status fortschreiben (v0.1)
// Übernimmt Claudes Abgleich, prüft ihn gegen das Update und schreibt den Stand fort.
// Ausgabe: Status-Datei (nach Template), History-Kopie des alten Stands, Status-Daten (JSON).
const WORKFLOW = 'FinVault Status fortschreiben v0.1';
const STATE_DIR = '/vault/Finanzen/Trading/System/Automation/status-state';
const ROOT = '/vault/Finanzen/Trading/Research/Analysten/The Long Investor';
const ALTERUNG_TAGE = 15;
const ctx = $('Abgleich vorbereiten').first().json;
const resp = $input.first().json;
const upd = ctx.upd;
const nachtrag = !!ctx.nachtrag;
const U = { datum: upd.datum, update: upd.name };
const hinweise = [];

const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const clean = s => String(s == null ? '' : s).replace(/<\/?[a-zA-Z_][^>]*>/g, '').replace(/\[\[|\]\]/g, '').replace(/</g, '&lt;').replace(/>/g, '&gt;').trim();
const parseMaybe = v => { if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } } return v; };

// ---------- Claude-Antwort ----------
const tu = (resp.content || []).find(c => c.type === 'tool_use' && c.name === 'status_abgleich');
if (!tu) throw new Error('Claude hat keinen Abgleich geliefert: ' + JSON.stringify(resp).slice(0, 300));
const r = tu.input || {};
const entsch = new Map();
for (const d of (parseMaybe(r.bisherige_marken) || [])) if (d && d.id) entsch.set(String(d.id).trim(), { aktion: String(d.aktion || '').trim(), neue_marke: String(d.neue_marke || '').trim(), beleg: clean(d.beleg) });
const abschn = parseMaybe(r.abschnitte) || {};
const usage = resp.usage || {};
const kostenCent = Math.round(((usage.input_tokens || 0) * 0.10 + (usage.output_tokens || 0) * 0.50) / 1e6 * 100 * 10000) / 10000;

// ---------- Stand übernehmen oder anlegen ----------
const alt = ctx.state ? JSON.parse(JSON.stringify(ctx.state)) : null;
const st = ctx.state ? JSON.parse(JSON.stringify(ctx.state)) : {
  schema: 'status-v1', ticker: upd.ticker, kategorie: upd.kategorie, instrument: upd.instrument || '',
  ticker_dir: upd.ticker_dir, stand: null, next_id: 1, marken: [], abschnitte: {}, updates: [], konzepte: [],
  letzte_aenderung: null, pruefhinweise: [],
};
if (upd.instrument && !st.instrument) st.instrument = upd.instrument;

// ---------- Belege und Zahlen prüfen ----------
const quelle = norm(upd.kern);
const belegOk = b => {
  const n = norm(b);
  if (!n) return false;
  if (quelle.includes(n)) return true;
  const w = n.split(' ').filter(x => x.length > 3);
  return w.length >= 3 && w.filter(x => quelle.includes(x)).length / w.length >= 0.6;
};
const zahlVarianten = s => {
  const v = new Set([Number(s.replace(',', '.'))]);
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) v.add(Number(s.replace(/\./g, '').replace(',', '.')));
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) v.add(Number(s.replace(/,/g, '')));
  return [...v].filter(x => !isNaN(x));
};
const zahlen = t => (String(t).match(/\d+(?:[.,]\d+)*/g) || []).flatMap(zahlVarianten);
const bekannt = new Set([...zahlen(upd.kern), ...(st.marken || []).flatMap(m => [m.wert, m.wert_bis]).filter(x => x != null),
  ...Object.values(st.abschnitte || {}).flatMap(a => zahlen(a.text || ''))].map(x => Math.round(x * 1000)));
const pruefeZahlen = (key, text) => {
  const fremd = [...new Set((String(text).match(/\d+(?:[.,]\d+)*/g) || []).filter(s => !zahlVarianten(s).some(x => x <= 10 || bekannt.has(Math.round(x * 1000)))))];
  if (fremd.length) hinweise.push(`${key}: Zahl(en) ${fremd.join(', ')} stehen weder im Update noch im bisherigen Stand`);
};

// ---------- Marken abgleichen ----------
const nah = (a, b) => (a == null && b == null) || (a != null && b != null && Math.abs(a - b) <= Math.max(0.01, Math.abs(b) * 0.005));
const gleich = (m, n) => nah(m.wert, n.wert) && nah(m.wert_bis, n.wert_bis) && (m.wert != null || norm(m.beschreibung) === norm(n.beschreibung));
const nByid = Object.fromEntries(upd.marken.map(n => [n.id, n]));
const benutzt = new Set();
const neuIds = [], bestIds = [], nichtIds = [], geaendert = [], aufgehoben = [];
const neueMarke = (n) => {
  const m = { id: 'M' + st.next_id++, art: n.art, wert: n.wert, wert_bis: n.wert_bis, waehrung: n.waehrung || 'USD', beschreibung: n.beschreibung,
    status: 'aktiv', erstmals: { ...U }, zuletzt: { ...U } };
  st.marken.push(m); benutzt.add(n.id); return m;
};
for (const m of st.marken.filter(x => x.status === 'aktiv')) {
  let d = entsch.get(m.id) || { aktion: 'nicht_erwaehnt' };
  let n = d.neue_marke && nByid[d.neue_marke] && !benutzt.has(d.neue_marke) ? nByid[d.neue_marke] : null;
  const auto = upd.marken.find(x => !benutzt.has(x.id) && x.art === m.art && gleich(m, x));
  if (d.aktion === 'bestaetigt' || d.aktion === 'geaendert') {
    if (!n || (d.aktion === 'bestaetigt' && !gleich(m, n))) n = auto || n;
    if (!n) d = { aktion: 'nicht_erwaehnt' };
    else if (gleich(m, n)) d = { ...d, aktion: 'bestaetigt' };
    else if (d.aktion === 'bestaetigt') d = { aktion: 'nicht_erwaehnt' };
  } else if (d.aktion === 'aufgehoben') {
    if (!belegOk(d.beleg)) { hinweise.push(`${m.id} (${m.wert}): "aufgehoben" ohne nachvollziehbaren Beleg im Update – bleibt gültig`); d = auto ? { aktion: 'bestaetigt' } : { aktion: 'nicht_erwaehnt' }; n = auto; }
  } else { d = auto ? { aktion: 'bestaetigt' } : { aktion: 'nicht_erwaehnt' }; n = auto; }
  if (nachtrag && (d.aktion === 'geaendert' || d.aktion === 'aufgehoben')) { d = auto ? { aktion: 'bestaetigt' } : { aktion: 'nicht_erwaehnt' }; n = auto; }

  if (d.aktion === 'bestaetigt') {
    benutzt.add(n.id);
    if (U.datum < m.erstmals.datum) m.erstmals = { ...U };
    if (U.datum >= m.zuletzt.datum) { m.zuletzt = { ...U }; if (!nachtrag && n.beschreibung) m.beschreibung = n.beschreibung; }
    bestIds.push(m.id);
  } else if (d.aktion === 'geaendert') {
    const nm = neueMarke(n);
    m.status = 'ersetzt'; m.ende = { ...U, grund: d.beleg || '' }; m.ersetzt_durch = nm.id; nm.ersetzt = m.id;
    if (!d.beleg) hinweise.push(`${m.id} → ${nm.id}: Änderung ohne Zitat`);
    geaendert.push({ alt: m.id, neu: nm.id });
  } else if (d.aktion === 'aufgehoben') {
    m.status = 'aufgehoben'; m.ende = { ...U, grund: d.beleg };
    aufgehoben.push(m.id);
  } else nichtIds.push(m.id);
}
for (const n of upd.marken) {
  if (benutzt.has(n.id)) continue;
  // Nachtrag: keine Marke wiederbeleben, die ein neueres Update bereits beendet hat – nur "erstmals" vorziehen
  const beendet = nachtrag && st.marken.find(m => m.status !== 'aktiv' && m.art === n.art && gleich(m, n) && m.ende && m.ende.datum > U.datum);
  if (beendet) { if (U.datum < beendet.erstmals.datum) beendet.erstmals = { ...U }; benutzt.add(n.id); continue; }
  neuIds.push(neueMarke(n).id);
}

// ---------- Abschnitte ----------
const KEYS = ['kurzueberblick', 'primaerszenario', 'alternatives_szenario', 'trigger', 'elliott', 'trend', 'gleitende_durchschnitte', 'fibonacci', 'ausstehende_bestaetigungen', 'risiken'];
const LISTEN = ['trigger', 'gleitende_durchschnitte', 'fibonacci', 'ausstehende_bestaetigungen', 'risiken'];
const aktualisiert = [];
for (const k of KEYS) {
  const d = parseMaybe(abschn[k]) || { aktion: 'unveraendert' };
  const old = st.abschnitte[k] && st.abschnitte[k].text ? st.abschnitte[k] : null;
  let text = clean(d.text);
  if (LISTEN.includes(k) && text) text = text.split('\n').map(l => l.trim()).filter(Boolean).map(l => l.startsWith('- ') ? l : `- ${l.replace(/^[-*•]\s*/, '')}`).join('\n');
  const aktion = String(d.aktion || '').trim();
  if (nachtrag) {
    if (!old && aktion === 'aktualisiert' && text) { st.abschnitte[k] = { text, stand: { ...U }, bestaetigt: null }; aktualisiert.push(k); pruefeZahlen(k, text); }
    else if (old && aktion === 'bestaetigt' && U.datum < old.stand.datum) { /* ältere Bestätigung ändert nichts */ }
    continue;
  }
  if (aktion === 'aktualisiert' && text) { st.abschnitte[k] = { text, stand: { ...U }, bestaetigt: null }; aktualisiert.push(k); pruefeZahlen(k, text); }
  else if (aktion === 'bestaetigt' && old) old.bestaetigt = { ...U };
}

// ---------- Kopfdaten, Verlauf, Konzepte ----------
for (const l of ctx.links || []) if (!st.konzepte.some(x => x.ziel === l.ziel)) st.konzepte.push(l);
st.updates.push({ ...U, nachtrag, neu: neuIds.length, bestaetigt: bestIds.length, geaendert: geaendert.length, aufgehoben: aufgehoben.length,
  abschnitte: aktualisiert.length, verarbeitet_am: new Date().toISOString(), kosten_cent: kostenCent });
st.updates.sort((a, b) => (a.datum + a.update).localeCompare(b.datum + b.update));
if (!nachtrag) {
  st.stand = { ...U };
  st.letzte_aenderung = { ...U, neu: neuIds, bestaetigt: bestIds, nicht_erwaehnt: nichtIds, geaendert, aufgehoben, abschnitte: aktualisiert };
} else if (st.letzte_aenderung) {
  st.letzte_aenderung.nachtraege = [...(st.letzte_aenderung.nachtraege || []), { ...U, neu: neuIds }];
}
st.pruefhinweise = [...(st.pruefhinweise || []), ...hinweise.map(h => `${U.datum}: ${h}`)].slice(-15);
st.aktualisiert_am = new Date().toISOString();
st.verarbeitung = { workflow: WORKFLOW, prompt_version: ctx.prompt_version, modell: ctx.model, kosten_cent: kostenCent };

// ---------- Rendern nach Template ----------
function parseTemplate(t) {
  const txt = String(t).replace(/\r/g, '').split('\n').map(l => l.replace(/\s+$/, '')).join('\n');
  const m = txt.match(/^---\s*\n([\s\S]*?)\n---\s*\n?([\s\S]*)$/);
  const fmKeys = [];
  if (m) for (const l of m[1].split('\n')) { const k = l.match(/^([^\s:#-][^:]*):/); if (k) fmKeys.push(k[1].trim()); }
  const blocks = []; let cur = null;
  for (const l of (m ? m[2] : txt).split('\n')) {
    const h = l.match(/^(#{1,6})\s+(.*)$/);
    if (h) { cur = { level: h[1].length, title: h[2].trim(), lines: [] }; blocks.push(cur); continue; }
    if (cur && l.trim()) cur.lines.push(l);
  }
  return { fmKeys, blocks };
}
const TPL = parseTemplate(ctx.template);
const ART = { unterstuetzung: 'Unterstützung', widerstand: 'Widerstand', zone: 'Kauf-/Beobachtungszone', kursziel: 'Kursziel', invalidation: 'Invalidation' };
const NAMEN = { kurzueberblick: 'Kurzüberblick', primaerszenario: 'Primärszenario', alternatives_szenario: 'Alternatives Szenario', trigger: 'Trigger', elliott: 'Elliott-Wellen-Stand', trend: 'Trendstruktur', gleitende_durchschnitte: 'Gleitende Durchschnitte', fibonacci: 'Fibonacci-Niveaus', ausstehende_bestaetigungen: 'Ausstehende Bestätigungen', risiken: 'Unsicherheiten und Risiken' };
const q = s => JSON.stringify(s == null ? '' : String(s));
const deD = d => d ? `${d.slice(8, 10)}.${d.slice(5, 7)}.${d.slice(0, 4)}` : '';
const lk = u => u ? `[[${u.update}|${deD(u.datum)}]]` : '';
const tage = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 864e5);
const deN = v => Number(v).toLocaleString('de-DE', { maximumFractionDigits: 2 });
const wertTxt = m => m.wert == null ? '' : (m.wert_bis != null ? `${deN(m.wert)} – ${deN(m.wert_bis)}` : deN(m.wert)) + ` ${m.waehrung || 'USD'}`;
const kurz = m => [wertTxt(m) ? `**${wertTxt(m)}**` : '', m.beschreibung].filter(Boolean).join(' – ');

function render(s, archiv) {
  const latest = s.stand ? s.stand.datum : U.datum;
  const alter = d => { const t = d ? tage(d, latest) : 0; return t > ALTERUNG_TAGE ? ` · ⚠️ seit ${t} Tagen nicht bestätigt` : ''; };
  const byId = Object.fromEntries(s.marken.map(m => [m.id, m]));
  const markenListe = art => {
    const akt = s.marken.filter(m => m.art === art && m.status === 'aktiv').sort((a, b) => (b.wert ?? -1) - (a.wert ?? -1));
    const weg = s.marken.filter(m => m.art === art && m.status !== 'aktiv' && m.ende && tage(m.ende.datum, latest) <= 60);
    return [
      ...akt.map(m => `- ${kurz(m)} · gültig · erstmals ${lk(m.erstmals)} · zuletzt bestätigt ${lk(m.zuletzt)}${alter(m.zuletzt.datum)}`),
      ...weg.map(m => `- ~~${kurz(m)}~~ · ${m.status === 'ersetzt' && byId[m.ersetzt_durch] ? `ersetzt durch **${wertTxt(byId[m.ersetzt_durch]) || byId[m.ersetzt_durch].beschreibung}**` : 'nicht mehr gültig'} seit ${lk(m.ende)}${m.ende.grund ? ` („${m.ende.grund}“)` : ''}`),
    ].join('\n');
  };
  const abschnitt = k => {
    const a = s.abschnitte[k];
    if (!a || !a.text) return '';
    const best = a.bestaetigt && a.bestaetigt.datum > a.stand.datum ? a.bestaetigt : null;
    return `${a.text}\n\n*Stand: ${lk(a.stand)}${best ? ` · zuletzt bestätigt ${lk(best)}` : ''}${alter((best || a.stand).datum)}*`;
  };
  const la = s.letzte_aenderung;
  const aenderung = sub => {
    if (!la) return '';
    const t = norm(sub);
    if (t === 'neu') return la.neu.map(id => byId[id]).filter(Boolean).map(m => `- ${kurz(m)} · ${ART[m.art]}`).join('\n');
    if (t.startsWith('weiterhin')) return [
      ...la.bestaetigt.map(id => byId[id]).filter(m => m && m.status === 'aktiv').map(m => `- ${kurz(m)} · ${ART[m.art]} · bestätigt`),
      ...la.nicht_erwaehnt.map(id => byId[id]).filter(m => m && m.status === 'aktiv').map(m => `- ${kurz(m)} · ${ART[m.art]} · nicht erwähnt, gilt weiter`),
    ].join('\n');
    if (t.startsWith('geandert')) return [
      ...la.geaendert.map(g => [byId[g.alt], byId[g.neu]]).filter(x => x[0] && x[1]).map(([a, b]) => `- ${ART[a.art]}: ${wertTxt(a) || a.beschreibung} → **${wertTxt(b) || b.beschreibung}**${a.ende && a.ende.grund ? ` („${a.ende.grund}“)` : ''}`),
      ...(la.abschnitte.length ? [`- Aktualisierte Abschnitte: ${la.abschnitte.map(k => NAMEN[k]).join(', ')}`] : []),
    ].join('\n');
    if (t.startsWith('nicht mehr')) return la.aufgehoben.map(id => byId[id]).filter(Boolean).map(m => `- ${kurz(m)} · ${ART[m.art]}${m.ende && m.ende.grund ? ` („${m.ende.grund}“)` : ''}`).join('\n');
    return '';
  };
  const content = (title) => {
    const t = norm(title);
    if (t.startsWith('kurzuberblick')) return abschnitt('kurzueberblick');
    if (t.includes('primarszenario')) return abschnitt('primaerszenario');
    if (t.startsWith('alternatives')) return abschnitt('alternatives_szenario');
    if (t.includes('trigger')) return abschnitt('trigger');
    if (t.startsWith('unterstutzung')) return markenListe('unterstuetzung');
    if (t.startsWith('widerstand')) return markenListe('widerstand');
    if (t.startsWith('kauf')) return markenListe('zone');
    if (t.startsWith('kursziel')) return markenListe('kursziel');
    if (t.startsWith('invalidation')) return markenListe('invalidation');
    if (t.startsWith('elliott')) return abschnitt('elliott');
    if (t.startsWith('trend')) return abschnitt('trend');
    if (t.startsWith('gleitende')) return abschnitt('gleitende_durchschnitte');
    if (t.startsWith('fibonacci')) return abschnitt('fibonacci');
    if (t.includes('ausstehende')) return abschnitt('ausstehende_bestaetigungen');
    if (t.startsWith('anderungen durch')) return la ? `Bezug: ${lk(la)}${(la.nachtraege || []).length ? ` · ergänzt durch Nachtrag ${la.nachtraege.map(lk).join(', ')}` : ''}` : '';
    if (t.startsWith('unsicherheiten')) return abschnitt('risiken');
    if (t.startsWith('verwendete')) return [...s.updates].reverse().map(u => `- ${lk(u)} – neu ${u.neu}, bestätigt ${u.bestaetigt}, geändert ${u.geaendert}, nicht mehr gültig ${u.aufgehoben}, Abschnitte aktualisiert ${u.abschnitte}${u.nachtrag ? ' (Nachtrag)' : ''}`).join('\n');
    return null;
  };
  // Frontmatter: Template-Felder in Template-Reihenfolge, danach Zusatzfelder
  const known = {
    typ: 'analysten-wertpapierstatus', status: archiv ? 'archiviert' : 'review', quelle: 'Patreon', analyst: 'The Long Investor',
    instrument: q(s.instrument || s.ticker), ticker: s.ticker, letztes_update: s.stand ? q(`[[${s.stand.update}]]`) : '""', zeiteinheit: '""',
  };
  const fm = ['---'];
  for (const k of TPL.fmKeys) fm.push(`${k}: ${known[norm(k).replace(/ /g, '_')] ?? ''}`.replace(/\s+$/, ''));
  fm.push(
    `stand: ${s.stand ? s.stand.datum : ''}`,
    `erstes_update: ${s.updates.length ? q(`[[${s.updates[0].update}]]`) : '""'}`,
    `anzahl_updates: ${s.updates.length}`,
    `theorie:${s.konzepte.length ? '\n' + s.konzepte.map(c => `  - ${q(`[[${c.ziel}|${c.begriff}]]`)}`).join('\n') : ' []'}`,
    `pruefhinweise:${(s.pruefhinweise || []).length ? '\n' + s.pruefhinweise.map(h => `  - ${q(h)}`).join('\n') : ' []'}`,
    `aktualisiert_am: ${s.aktualisiert_am || ''}`,
    'verarbeitung:',
    `  workflow: ${q(WORKFLOW)}`,
    `  prompt_version: ${q((s.verarbeitung || {}).prompt_version || '')}`,
    `  modell: ${q((s.verarbeitung || {}).modell || '')}`,
    '---', '');
  const out = [fm.join('\n')];
  let inVerwendet = false;
  for (const b of TPL.blocks) {
    if (b.level === 1) {
      out.push('# ' + b.title.replace(/\{\{\s*instrument\s*\}\}/gi, s.ticker) + (archiv ? ` (Stand ${deD(s.stand && s.stand.datum)})` : ''), '');
      out.push(`> **Datei-Stand:** ${s.stand ? lk(s.stand) : '–'} · ${s.updates.length} Update(s) seit ${deD(s.updates[0] && s.updates[0].datum)} · Einschätzungen des Analysten, keine Anlageempfehlung.`, '');
      continue;
    }
    out.push(`${'#'.repeat(b.level)} ${b.title}`);
    let c = null;
    const parent = TPL.blocks.slice(0, TPL.blocks.indexOf(b)).reverse().find(x => x.level < b.level);
    if (b.level === 3 && parent && norm(parent.title).startsWith('anderungen durch')) c = aenderung(b.title);
    else c = content(b.title);
    if (c == null) c = b.lines.filter(l => !/\[\[[^\]]*\]\]/.test(l)).join('\n');
    out.push(c ? c + '\n' : '');
  }
  let text = out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n';
  // Theorie-Links: je Begriff das erste Vorkommen im Text verlinken (nicht in Überschriften, Kopfzeile, Updateliste)
  const esc = x => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const [head, ...rest] = text.split(/\n---\n/);
  let body = rest.join('\n---\n');
  const lines = body.split('\n');
  for (const c of [...s.konzepte].sort((a, b) => b.begriff.length - a.begriff.length)) {
    const re = new RegExp(`(?<![\\p{L}\\p{N}])${esc(c.begriff)}(?![\\p{L}\\p{N}])`, 'iu');
    let stop = false;
    for (let i = 0; i < lines.length && !stop; i++) {
      const l = lines[i];
      if (/^#{1,6}\s/.test(l) && /verwendete/i.test(l)) break;
      if (/^#{1,6}\s/.test(l) || /^>/.test(l)) continue;
      const parts = l.split(/(\[\[[^\]]*\]\])/);
      for (let j = 0; j < parts.length; j += 2) {
        if (re.test(parts[j])) { parts[j] = parts[j].replace(re, x => `[[${c.ziel}|${x}]]`); stop = true; break; }
      }
      if (stop) lines[i] = parts.join('');
    }
  }
  return head + '\n---\n' + lines.join('\n');
}

// ---------- Ausgabe ----------
const T = st.ticker;
const statusDir = `${st.ticker_dir}/Aktueller Stand`;
if (!statusDir.startsWith(ROOT + '/') || statusDir.includes('..') || !/^[A-Za-z0-9 ._\/&-]+$/.test(statusDir)) throw new Error('Unzulässiger Status-Pfad: ' + statusDir);
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const files = [];
let cmd = `mkdir -p "${statusDir}"`;
if (!alt) cmd += ` && if [ -f "${statusDir}/${T} - Aktueller Analystenstand.md" ]; then mkdir -p "${statusDir}/_History" && mv "${statusDir}/${T} - Aktueller Analystenstand.md" "${statusDir}/_History/${T} - Aktueller Analystenstand (alter Flow).md"; fi`;
files.push({ kind: 'status', target_dir: statusDir, command: cmd, target_path: `${statusDir}/${T} - Aktueller Stand.md`, file_name: `${T} - Aktueller Stand.md`, content_b64: b64(render(st, false)) });
if (alt && alt.stand) {
  const hn = `${T} - Stand ${alt.stand.datum} (${alt.updates.length} Updates).md`;
  files.push({ kind: 'history', target_dir: `${statusDir}/_History`, command: `mkdir -p "${statusDir}/_History"`, target_path: `${statusDir}/_History/${hn}`, file_name: hn, content_b64: b64(render(alt, true)) });
}
files.push({ kind: 'state', target_dir: STATE_DIR, command: `mkdir -p "${STATE_DIR}"`, target_path: `${STATE_DIR}/${T}.json`, file_name: `${T}.json`, content_b64: b64(JSON.stringify(st, null, 2) + '\n') });
return files.map(f => ({ json: { ...f, ticker: T, update: U.update, nachtrag, neu: neuIds.length, bestaetigt: bestIds.length, geaendert: geaendert.length, aufgehoben: aufgehoben.length, hinweise: hinweise.length } }));

// Flow B – Als Datei (v0.1): Inhalte aus "Status fortschreiben" als Binärdaten zum Schreiben
const src = $('Status fortschreiben').all();
return src.map(i => ({
  json: { target_path: i.json.target_path, kind: i.json.kind, ticker: i.json.ticker },
  binary: { data: { data: i.json.content_b64, mimeType: i.json.kind === 'state' ? 'application/json' : 'text/markdown', fileName: i.json.file_name, fileExtension: i.json.kind === 'state' ? 'json' : 'md' } },
}));
